// The weekly client check's app half (core #2142): the official PeerTube app's own parsers, run on what this module's
// stack answers. Copied into the app's test/ directory at its newest release tag and run there, so the models are the
// app's, generated by its own build step, never a copy kept here.
//
// Each test reads one endpoint the app reads (core ADR 1004 for the module, tube ADR 0004 for the list) and hands the
// body to the same `fromJson` the app's datasource hands it to. A model that reads a field the module does not answer
// throws here, in the week it changes, instead of in a user's app.
import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:peertube/features/account/account_model.dart';
import 'package:peertube/features/channel/channel_model.dart';
import 'package:peertube/features/server/server_stats_model.dart';
import 'package:peertube/features/video/video_model.dart';
import 'package:peertube/shared/config/config_models.dart';
import 'package:peertube/shared/const/const.dart';
import 'package:peertube/shared/current_platform/current_platform_models.dart';
import 'package:peertube/shared/utils/json_parser.dart';
import 'package:peertube/shared/utils/tools.dart';

final String host =
    Platform.environment['ALCIFRA_CHECK_HOST'] ?? 'https://tube.test';

// The check's edge signs its certificate with its own authority (Caddyfile); the run hands its root over here.
SecurityContext trust() {
  final ca = Platform.environment['ALCIFRA_CHECK_CA'];
  final context = SecurityContext(withTrustedRoots: true);
  if (ca != null) {
    context.setTrustedCertificates(ca);
  }
  return context;
}

Future<HttpClientResponse> get(Uri uri, {String? range}) async {
  final client = HttpClient(context: trust());
  final request = await client.getUrl(uri);
  if (range != null) {
    request.headers.set(HttpHeaders.rangeHeader, range);
  }
  return request.close();
}

Future<dynamic> getJson(String path) async {
  final response = await get(Uri.parse('$host/api/v1/$path'));
  expect(response.statusCode, 200, reason: 'GET /api/v1/$path');
  return jsonDecode(await utf8.decoder.bind(response).join());
}

void main() {
  late ConfigServer config;
  late List<Video> videos;
  late VideoDetails details;

  test('config parses, and the server is not too old for this app', () async {
    config = ConfigServer.fromJson(await getJson('config') as Map<String, dynamic>);
    expect(
      compareVersions(config.serverVersion, PEERTUBE_MIN_VERSION) >= 0,
      isTrue,
      reason: 'the app refuses ${config.serverVersion} below $PEERTUBE_MIN_VERSION',
    );
  });

  test('about parses (what the app reads to switch to a server)', () async {
    final about = await getJson('config/about') as Map<String, dynamic>;
    PlatformAPI.fromJson(about['instance'] as Map<String, dynamic>);
  });

  test('server stats parse', () async {
    ServerStats.fromJson(await getJson('server/stats') as Map<String, dynamic>);
  });

  test('the video list parses and holds the seeded clip', () async {
    final page = await getJson('videos?sort=-publishedAt&start=0&count=25') as Map<String, dynamic>;
    videos = parseJsonList(page['data'], Video.fromJson);
    expect(videos, isNotEmpty);
  });

  test('a video\'s details parse, and its file answers a range', () async {
    details = VideoDetails.fromJson(
      await getJson('videos/${videos.first.uuid}') as Map<String, dynamic>,
    );
    expect(details.files, isNotEmpty, reason: 'the player falls back to files[0]');
    final file = await get(details.files.first.fileUrl, range: 'bytes=0-99');
    expect(file.statusCode, 206, reason: 'a range on ${details.files.first.fileUrl}');
    await file.drain<void>();
  });

  test('the channel parses', () async {
    VideoChannelDetails.fromJson(
      await getJson('video-channels/${details.channel.name}') as Map<String, dynamic>,
    );
  });

  test('the account parses', () async {
    AccountDetails.fromJson(
      await getJson('accounts/${details.account.name}') as Map<String, dynamic>,
    );
  });
}
